struct Sequence {
    x: Int,
    y: Int,
}

fn term(s: Sequence, n: Int) -> Int {
    if n == 1 {
        s.x
    } else if n == 2 {
        s.y
    } else {
        term(Sequence { x: s.y, y: s.x + s.y }, n - 1)
    }
}

